arguments.command:
curl -s -H "Authorization: Bearer <TOKEN>" "https://www.googleapis.com/calendar/v3/calendars/primary/events?singleEvents=true&maxResults=250" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('items',[]):
    end=e.get('end',{}).get('dateTime','?')
    if end.endswith('15:30:00-07:00') or '15:30:00' in end:
        print(e['id'],'|',e.get('summary'),'|',e.get('start'),'->',e.get('end'),'|',e.get('location'),'|',e.get('description','')[:80])
print('---ALL---')
for e in d.get('items',[]):
    print(e['id'],'|',e.get('summary'),'|',e.get('start',{}).get('dateTime'),'->',e.get('end',{}).get('dateTime'),'|',e.get('location'))
"

